insert into public.challenges(id,title,prompt,options,challenge_type,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('a8eb6101-cd86-54b9-8c39-e3b3529b0543','AI audit: supplier reliability 1','The AI says Supplier A is “the most reliable option” because it had the fewest reported delays last year. What is the most important challenge to raise before relying on the answer?','["The writing style is too confident.", "Reported delays may reflect reporting quality and project mix, not true reliability.", "The answer should be longer.", "AI should never be used for this kind of task."]'::jsonb,'ai_answer_audit',35,true,true,'construction',true,1) on conflict(id) do nothing;
insert into public.challenge_answer_keys(challenge_id,correct_index,explanation,thinking_principle,application,error_patterns) values ('a8eb6101-cd86-54b9-8c39-e3b3529b0543',1,'The core issue is that reported delays may reflect reporting quality and project mix, not true reliability. The problem is evidential, not merely stylistic.','Fluency and confidence are not evidence. Verify the claim, its source and the assumptions that connect evidence to conclusion.','When AI produces a polished recommendation, test the evidential chain before acting on it.','{"0": "evidence_neglect", "2": "evidence_neglect", "3": "evidence_neglect"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
insert into public.challenge_skill_mapping(challenge_id,skill_id,weight) values ('a8eb6101-cd86-54b9-8c39-e3b3529b0543','2f70ee86-15d9-5d3c-9e3d-6ac2bcb7faf5',1.0) on conflict do nothing;
