insert into public.challenges(id,title,prompt,options,challenge_type,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('a991a1e8-f544-5a76-9340-6cdbb9a05423','Correlation challenge 1','In a construction dataset, teams using an AI assistant finish work 18% faster. What can you conclude from this observation alone?','["The AI assistant caused the 18% improvement.", "The relationship proves the assistant is worth buying.", "Use of the assistant is associated with faster completion, but selection effects and other causes remain possible.", "The data is useless unless it comes from a laboratory."]'::jsonb,'correlation_or_causation',42,true,true,'construction',true,61) on conflict(id) do nothing;
insert into public.challenge_answer_keys(challenge_id,correct_index,explanation,thinking_principle,application,error_patterns) values ('a991a1e8-f544-5a76-9340-6cdbb9a05423',2,'The observation establishes association, not causation. Faster teams may be more likely to adopt the assistant, or other changes may explain the result.','Before moving from correlation to causation, identify plausible confounders and ask what comparison would distinguish them.','AI-generated analyses often slide from “associated with” to “caused by”; challenge that inference explicitly.','{"0": "causal_inference_error", "1": "causal_inference_error", "3": "causal_inference_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
