insert into public.challenge_answer_keys(challenge_id,correct_index,explanation,thinking_principle,application,error_patterns) values ('e557604b-6cb7-5846-904a-448cca25525e',2,'The observation establishes association, not causation. Faster teams may be more likely to adopt the assistant, or other changes may explain the result.','Before moving from correlation to causation, identify plausible confounders and ask what comparison would distinguish them.','AI-generated analyses often slide from “associated with” to “caused by”; challenge that inference explicitly.','{"0": "causal_inference_error", "1": "causal_inference_error", "3": "causal_inference_error"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
