insert into public.challenges(id,title,prompt,options,challenge_type,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('976c3366-b1f1-5a17-bb88-bb322fc47756','The missing question 1','A construction team recommends automating a recurring decision because it takes 300 staff hours per month. Which question is most important before approving automation?','["Can the interface use the company colours?", "What is the cost and consequence of a wrong automated decision, and where is independent verification required?", "Can the project be announced this quarter?", "Which AI model has the largest parameter count?"]'::jsonb,'missing_question',50,true,true,'construction',true,73) on conflict(id) do nothing;
insert into public.challenge_answer_keys(challenge_id,correct_index,explanation,thinking_principle,application,error_patterns) values ('976c3366-b1f1-5a17-bb88-bb322fc47756',1,'The key missing question is about decision risk, error consequence and control design, not cosmetic or model-brand features.','A good question reduces decision-relevant uncertainty; it is not simply an interesting question.','Before delegating judgement to AI, ask what failure looks like and how it will be detected.','{"0": "premature_closure", "2": "premature_closure", "3": "premature_closure"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
