insert into public.challenges(id,title,prompt,options,challenge_type,difficulty,is_diagnostic,confidence_required,industry,is_published,sort_order) values ('babdb6e9-af46-5ba9-a0b0-ac19f1f9afd2','Decide with incomplete evidence 1','An AI tool recommends a high-impact action in construction, but the source data is incomplete and the downside of error is material. What is the best next step?','["Accept the recommendation because delay also has a cost.", "Reject AI permanently.", "Identify the missing decision-critical information, obtain independent verification, and use a reversible step if action cannot wait.", "Ask the AI to express the answer with more confidence."]'::jsonb,'decision_under_uncertainty',55,false,true,'construction',true,83) on conflict(id) do nothing;
insert into public.challenge_answer_keys(challenge_id,correct_index,explanation,thinking_principle,application,error_patterns) values ('babdb6e9-af46-5ba9-a0b0-ac19f1f9afd2',2,'The proportionate response manages both uncertainty and downside: obtain the most decision-relevant evidence and preserve reversibility where possible.','Under uncertainty, decision quality comes from managing downside, information value and reversibility—not pretending uncertainty disappears.','AI is most dangerous when uncertainty is hidden. Make uncertainty operational by linking it to verification and escalation.','{"0": "overconfidence", "1": "overconfidence", "3": "overconfidence"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
