insert into public.challenge_answer_keys(challenge_id,correct_index,explanation,thinking_principle,application,error_patterns) values ('7df51da9-5b2c-57d2-92d2-56c2110e75d9',2,'The stronger framing separates the problem from a preselected solution and asks about root causes and alternative interventions.','Do not embed the desired solution inside the problem statement.','AI projects fail when “use AI” becomes the objective. Frame the outcome first, then compare interventions.','{"0": "solutioneering", "1": "solutioneering", "3": "solutioneering"}'::jsonb) on conflict(challenge_id) do update set correct_index=excluded.correct_index,explanation=excluded.explanation,thinking_principle=excluded.thinking_principle,application=excluded.application,error_patterns=excluded.error_patterns;
